-- instance; change the schema with a new file (sql/003_...sql), never by
-- editing this one after it has run.
CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  size TEXT NOT NULL,
  delivery_day TEXT NOT NULL,
  card_message TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  price_eur INTEGER NOT NULL,
