const actor = `// The app's server half. placeOrder saves a customer's order (the price is
// set here, from the size, so the page can't send a wrong one); listOrders
// checks Ines's private code and returns this week's orders.
const sql = use('sql')
const room = use('room')

// The code for the private orders page. Change it here to change it everywhere.
const ORDERS_CODE = 'ines2026'

const PRICES: Record<string, number> = { small: 25, medium: 35, large: 50 }

defineActor({
  actions: {
    placeOrder: defineAction({
      requires: 'interact',
      args: {
        type: 'object',
        required: ['size', 'deliveryDay', 'name', 'phone'],
        additionalProperties: false,
        properties: {
          size: { type: 'string', enum: ['small', 'medium', 'large'] },
          deliveryDay: { type: 'string', enum: ['Tuesday', 'Friday'] },
          cardMessage: { type: 'string', maxLength: 300 },
          name: { type: 'string', minLength: 1, maxLength: 100 },
          phone: { type: 'string', minLength: 5, maxLength: 30 },
        },
      },
      result: {
        type: 'object',
        required: ['id', 'priceEur'],
        properties: { id: { type: 'integer' }, priceEur: { type: 'integer' } },
      },
      run(ctx, { size, deliveryDay, cardMessage, name, phone }) {
        const who = name.trim()
        const tel = phone.trim()
        if (!who) ctx.fail('invalid_argument', 'name is empty')
        if (!tel) ctx.fail('invalid_argument', 'phone is empty')
        const price = PRICES[size]
        const msg = (cardMessage || '').trim().slice(0, 300)
        sql.run(
          'INSERT INTO orders (size, delivery_day, card_message, name, phone, price_eur, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
          size, deliveryDay, msg, who, tel, price, Date.now()
        )
        const row = sql.one('SELECT last_insert_rowid() AS id')
        // Tell every open orders page to refetch, so new orders appear live.
        room.emit('orders', {})
        return { id: row ? row.id : 0, priceEur: price }
      },
    }),

    listOrders: defineAction({
      requires: 'view',
      args: {
        type: 'object',
        required: ['code', 'weekStart'],
        additionalProperties: false,
        properties: {
          code: { type: 'string', minLength: 1, maxLength: 100 },
          weekStart: { type: 'integer', minimum: 0 },
        },
      },
      result: {
        type: 'array',
        items: {
          type: 'object',
          required: ['id', 'size', 'deliveryDay', 'cardMessage', 'name', 'phone', 'priceEur', 'createdAt'],
          properties: {
            id: { type: 'integer' },
            size: { type: 'string' },
            deliveryDay: { type: 'string' },
            cardMessage: { type: 'string' },
            name: { type: 'string' },
            phone: { type: 'string' },
            priceEur: { type: 'integer' },
            createdAt: { type: 'integer' },
          },
        },
      },
      run(ctx, { code, weekStart }) {
        if (code !== ORDERS_CODE) ctx.fail('invalid_argument', 'wrong code')
        return sql.all(
          'SELECT id, size, delivery_day AS deliveryDay, card_message AS cardMessage, name, phone, price_eur AS priceEur, created_at AS createdAt FROM orders WHERE created_at >= ? ORDER BY created_at ASC',
          weekStart
        )
      },
    }),
  },
})
`

