const mig = `-- Weekly quiz control: which week is live for pupils.
-- Weeks that already have questions (2026-W47) become real weeks, the newest one live,
-- so the quiz pupils see today does not change. Attempts are never touched: old weeks'
-- scores stay readable forever.
CREATE TABLE weeks (week TEXT PRIMARY KEY, live INTEGER NOT NULL DEFAULT 0);
INSERT INTO weeks (week, live) SELECT DISTINCT week, 0 FROM questions;
UPDATE weeks SET live = 1 WHERE week = (SELECT max(week) FROM weeks);
`;

const actor = `// The quiz's server half: this week's questions, scoring an attempt, the week's
// leaderboard with last week's champion, and the owner-only actions behind the
// teacher's desk page (per-week questions, which week is live, past weeks' boards).
// Built by a colleague in the bench; students take the quiz every week.
const sql = use('sql');

// Visitor levels that are staff (the teacher, or the owner of the app).
const STAFF_LEVELS = ['admin', 'owner', 'teacher'];
// Names that must never appear on a class board: staff, and the placeholder used by
// attempts recorded before students typed their own name.
const NOT_A_STUDENT = ['admin', 'administrator', 'teacher', 'student', 'anonymous'];

// ---------- week labels (ISO weeks like 2026-W47), no library needed ----------

function isoWeekFromMs(ms) {
  const dayNum = (new Date(ms).getUTCDay() + 6) % 7; // Mon=0 … Sun=6
  const thu = ms + (3 - dayNum) * 86400000; // that week's Thursday decides year + week
  const y = new Date(thu).getUTCFullYear();
  const jan4 = Date.UTC(y, 0, 4); // Jan 4 is always in week 1
  const jDay = (new Date(jan4).getUTCDay() + 6) % 7;
  const week = 1 + Math.round((thu - (jan4 - jDay * 86400000)) / (7 * 86400000));
  return y + '-W' + String(week).padStart(2, '0');
}

// The week label after the given one, across new-year boundaries ("2026-W53" -> "2027-W01").
function nextWeekLabel(label) {
  const m = /^(\\d{4})-W(\\d{2})$/.exec(label || '');
  if (!m) return null;
  const jan4 = Date.UTC(+m[1], 0, 4);
  const jDay = (new Date(jan4).getUTCDay() + 6) % 7;
  const monday1 = jan4 - jDay * 86400000; // Monday of that year's week 1
  return isoWeekFromMs(monday1 + (+m[2] - 1) * 7 * 86400000 + 7 * 86400000);
}

// What to pre-fill the teacher's "new week" box with: one past the newest week on file,
// or (nothing on file) the current week. She can always change it.
function suggestedNextWeek() {
  const row = sql.one('SELECT max(week) AS week FROM weeks');
  if (row && row.week) {
    const n = nextWeekLabel(row.week);
    if (n) return n;
  }
  return isoWeekFromMs(Date.now());
}

// The week pupils are answering right now: the one the teacher made live.
// (Before the weeks table existed it was simply the newest week with questions.)
function liveWeek() {
  const row = sql.one('SELECT week FROM weeks WHERE live = 1 ORDER BY week DESC LIMIT 1');
  if (row) return row.week;
  const q = sql.one('SELECT max(week) AS week FROM questions');
  return q && q.week ? q.week : null;
}

// ---------- names ----------

// A leaderboard shows first names only, whatever the roster or login gave us:
// "Ava Nguyen" -> Ava, "Nguyen, Ava" -> Ava, "ava.nguyen@school.org" -> Ava.
// Returns '' when there is nothing usable, so callers can refuse an empty name.
function cleanFirstName(raw) {
  let s = String(raw == null ? '' : raw).trim();
  if (!s) return '';
  if (s.includes('@')) s = s.slice(0, s.indexOf('@')).replace(/[._-]+/g, ' ');
  else if (s.includes(',')) s = s.split(',').pop();
  const first = (s.split(/\\s+/)[0] || '').replace(/[^A-Za-z'-]/g, '').slice(0, 20);
  if (!first) return '';
  // "AVA" -> "Ava", but "McDonald" and "O'Brien" keep their shape.
  const rest = first.slice(1);
  const r = rest === rest.toUpperCase() ? rest.toLowerCase() : rest;
  return first.charAt(0).toUpperCase() + r;
}

// The teacher's desk is for the app's owner only.
function requireOwner(ctx) {
  const level = String((ctx.visitor && ctx.visitor.level) || '').toLowerCase();
  if (level !== 'owner' && level !== 'admin') {
    throw new Error('Only the teacher who owns this quiz can do that.');
  }
}

// A week's board rows: one row per student, their best score that week, whoever reached
// it first listed first. We filter by the NAME the student typed, never by the visitor's
// account: in class the teacher is often logged in on the shared device, and filtering
// on that level would erase every student's score made from it.
function boardOf(week, limit) {
  return sql
    .all(
      "SELECT student, max(score) AS score, min(at) AS at FROM attempts WHERE week = ?" +
        " AND trim(student) <> ''" +
        " AND lower(trim(student)) NOT IN ('admin', 'administrator', 'teacher', 'student', 'anonymous')" +
        ' GROUP BY student ORDER BY score DESC, at ASC',
      week
    )
    .slice(0, limit)
    .map((r) => ({ name: cleanFirstName(r.student) || 'Student', score: r.score }));
}

