);

// 3. Build a 40-district x 5-month fixture (200 rows) on the TEST instance.
const districts = [];
for (let i = 1; i <= 40; i++) districts.push('Barrio ' + String(i).padStart(2, '0'));
const months = ['2024-01', '2024-02', '2024-03', '2024-04', '2024-05'];
const rows = [];
for (let i = 0; i < 40; i++) {
  const base = 420 + i * 22;
  months.forEach((m, mi) => rows.push({ district: districts[i], month: m, median_rent: base + mi * (5 + (i % 7)) }));
}
await fixtures.save('forty-districts', {
  description: 'Scale probe: 40 districts x 5 months = 200 rows, values 420-1500.',
  tables: { rents: rows },
});

