const failSpec = { ...spec, steps: spec.steps.map(s => (s.count === 200 ? { ...s, count: 199 } : s)) };
await scenarios.save('scale-forty-districts', failSpec);
const failRun = await scenarios.run('scale-forty-districts');

// 6. Restore and time the real run.
await scenarios.save('scale-forty-districts', spec);
